class Task {
  final String id, title;
  const Task(this.id, this.title);
}

// domain/repositories/task_repository.dart
abstract interface class TaskRepository {
  Future<List<Task>> getTasks();
}

// data/repositories/task_repository_impl.dart
class TaskRepositoryImpl implements TaskRepository {
  final Dio _dio;
  List<Task> _lastGood = const [];
  TaskRepositoryImpl(this._dio);

  @override
  Future<List<Task>> getTasks() async {
    try {
      final res = await _dio.get<List<dynamic>>('/tasks');
      _lastGood = (res.data ?? const []).map((e) {
        final m = e as Map<String, dynamic>;
        return Task(m['id'] as String, m['title'] as String);
      }).toList();
      return _lastGood;
    } on DioException {
      return _lastGood; // offline: show the last known list
    }
  }
}

