// Back-of-the-envelope estimate for a Tehran food-ordering app
class Estimate {
  final int dailyUsers;
  final int requestsPerUser;
  final double peakFactor;
  final double orderRate; // share of daily users who order
  final int orderBytes;

  const Estimate({
    required this.dailyUsers,
    required this.requestsPerUser,
    required this.peakFactor,
    required this.orderRate,
    required this.orderBytes,
  });

  double get avgQps => dailyUsers * requestsPerUser / 86400;
  double get peakQps => avgQps * peakFactor;
  int get ordersPerDay => (dailyUsers * orderRate).round();
  double get gbPerYear => ordersPerDay * orderBytes * 365 / 1e9;
}

void main() {
  const e = Estimate(dailyUsers: 500000, requestsPerUser: 20,
      peakFactor: 5, orderRate: 0.1, orderBytes: 1000);
  print('avg QPS: ${e.avgQps.toStringAsFixed(0)}'); // 116
  print('peak QPS: ${e.peakQps.toStringAsFixed(0)}'); // 579
  print('orders/day: ${e.ordersPerDay}'); // 50000
  print('orders GB/year: ${e.gbPerYear.toStringAsFixed(1)}'); // 18.3
}

