class TtlCache<K, V> {
  final Duration ttl;
  final _items = <K, (V, DateTime)>{};
  TtlCache(this.ttl);

  V? get(K key) {
    final entry = _items[key];
    if (entry == null) return null;
    if (DateTime.now().difference(entry.$2) > ttl) {
      _items.remove(key); // expired
      return null;
    }
    return entry.$1;
  }

  void set(K key, V value) => _items[key] = (value, DateTime.now());
  void invalidate(K key) => _items.remove(key);
}

