import 'package:dio/dio.dart';

class Menu {
  const Menu(this.items);
  final List<String> items;
}

// Cache-aside: read the cache first, go to the network on a miss
class MenuRepository {
  final Dio _dio;
  final _cache = <String, (Menu, DateTime)>{};
  static const _ttl = Duration(minutes: 5);
  MenuRepository(this._dio);

  Future<Menu> getMenu(String restaurantId) async {
    final hit = _cache[restaurantId];
    if (hit != null && DateTime.now().difference(hit.$2) < _ttl) {
      return hit.$1; // fresh hit: no network call
    }
    try {
      final res = await _dio.get<List<dynamic>>('/restaurants/$restaurantId/menu');
      final menu = Menu([for (final e in res.data ?? const []) e.toString()]);
      _cache[restaurantId] = (menu, DateTime.now());
      return menu;
    } on DioException {
      if (hit != null) return hit.$1; // stale beats an error screen
      rethrow;
    }
  }
  // Call when the server says "price changed" at checkout
  void invalidate(String restaurantId) => _cache.remove(restaurantId);
}

