import 'dart:math';
import 'package:dio/dio.dart';

// Retrying is safe only if the server can detect duplicates
Future<Response<dynamic>> placeOrder(Dio dio, Map<String, dynamic> order) async {
  final rnd = Random();
  final key = '${DateTime.now().microsecondsSinceEpoch}-${rnd.nextInt(1 << 32)}';

  for (var attempt = 0; ; attempt++) {
    try {
      return await dio.post<dynamic>(
        '/orders',
        data: order,
        options: Options(headers: {'Idempotency-Key': key}),
      );
    } on DioException catch (e) {
      final status = e.response?.statusCode ?? 0;
      final retryable = e.type == DioExceptionType.connectionTimeout ||
          e.type == DioExceptionType.receiveTimeout ||
          e.type == DioExceptionType.connectionError ||
          status >= 500;
      if (!retryable || attempt == 3) rethrow;
      // Exponential backoff with jitter: ~1s, 2s, 4s
      final waitMs = pow(2, attempt) * 1000 + rnd.nextInt(300);
      await Future<void>.delayed(Duration(milliseconds: waitMs.toInt()));
    }
  }
}

