// Never store CVV2 or the card PIN. Show and log only masked values.
String maskCard(String pan) {
  final d = pan.replaceAll(RegExp(r'\D'), '');
  if (d.length != 16) return '****';
  return '${d.substring(0, 4)}-${d.substring(4, 6)}**-****-${d.substring(12)}';
}

String maskNationalId(String id) =>
    id.length == 10 ? '******${id.substring(6)}' : '**********';

// Iranian national ID checksum (validate before sending)
bool isValidNationalId(String id) {
  if (!RegExp(r'^\d{10}$').hasMatch(id)) return false;
  if (RegExp(r'^(\d)\1{9}$').hasMatch(id)) return false; // 1111111111
  final digits = id.split('').map(int.parse).toList();
  var sum = 0;
  for (var i = 0; i < 9; i++) {
    sum += digits[i] * (10 - i);
  }
  final r = sum % 11;
  final check = digits[9];
  return r < 2 ? check == r : check == 11 - r;
}

void main() {
  print(maskCard('6037 9912 3456 7890')); // 6037-99**-****-7890
  print(maskNationalId('0012345679')); // ******5679
  print(isValidNationalId('0012345679')); // true
}

