import 'dart:convert';

// Reads "exp" from a JWT. Reading is NOT verifying: only the server verifies.
bool isExpired(String jwt, {Duration skew = const Duration(seconds: 30)}) {
  final parts = jwt.split('.');
  if (parts.length != 3) return true;
  final payload = utf8.decode(base64Url.decode(base64Url.normalize(parts[1])));
  final exp = (jsonDecode(payload) as Map<String, dynamic>)['exp'];
  if (exp is! int) return true;
  final expiry = DateTime.fromMillisecondsSinceEpoch(exp * 1000);
  return DateTime.now().add(skew).isAfter(expiry);
}

