import 'package:dio/dio.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
class AuthInterceptor extends QueuedInterceptor {
  AuthInterceptor(this._plain, this._storage);
  final Dio _plain; // same baseUrl, WITHOUT this interceptor: no loop, no deadlock
  final FlutterSecureStorage _storage;
  String? _access; // short-lived token: memory only
  @override
  void onRequest(RequestOptions options, RequestInterceptorHandler handler) {
    if (_access != null) options.headers['Authorization'] = 'Bearer $_access';
    handler.next(options);
  }
  @override
  Future<void> onError(DioException err, ErrorInterceptorHandler handler) async {
    final req = err.requestOptions;
    if (err.response?.statusCode != 401) return handler.next(err);
    try {
      if (_access == null || req.headers['Authorization'] == 'Bearer $_access') await _refresh();
      req.headers['Authorization'] = 'Bearer $_access';
      handler.resolve(await _plain.fetch<dynamic>(req));
    } on DioException catch (e) {
      if (e.response?.statusCode == 401) await _storage.delete(key: 'refresh_token');
      handler.next(e); // UI shows an error or the login screen
    }
  }
  Future<void> _refresh() async {
    final res = await _plain.post<Map<String, dynamic>>('/auth/refresh',
        data: {'refresh_token': await _storage.read(key: 'refresh_token')});
    _access = res.data!['access_token'] as String;
    await _storage.write(key: 'refresh_token', value: res.data!['refresh_token'] as String);
  }
}

