// Trust ONLY our bundled certificate, not every CA on the phone
Future<Dio> createPinnedDio() async {
  final pem = await rootBundle.load('assets/certs/api_example_ir.pem');
  final context = SecurityContext(withTrustedRoots: false)
    ..setTrustedCertificatesBytes(pem.buffer.asUint8List());

  final dio = Dio(BaseOptions(
    baseUrl: 'https://api.example.ir',
    connectTimeout: const Duration(seconds: 10),
  ));
  dio.httpClientAdapter = IOHttpClientAdapter(
    createHttpClient: () {
      final client = HttpClient(context: context);
      // Never return true here, not even "just for debug"
      client.badCertificateCallback = (cert, host, port) => false;
      return client;
    },
  );
  return dio;
}

