enum OrderStatus { placed, paid, accepted, preparing, pickedUp, delivered, cancelled }

// The only legal transitions. Anything else is a bug or an attack.
const _allowed = <OrderStatus, Set<OrderStatus>>{
  OrderStatus.placed: {OrderStatus.paid, OrderStatus.cancelled},
  OrderStatus.paid: {OrderStatus.accepted, OrderStatus.cancelled},
  OrderStatus.accepted: {OrderStatus.preparing, OrderStatus.cancelled},
  OrderStatus.preparing: {OrderStatus.pickedUp},
  OrderStatus.pickedUp: {OrderStatus.delivered},
};

class Order {
  final int id;
  final OrderStatus status;
  const Order(this.id, this.status);

  bool canMoveTo(OrderStatus next) => _allowed[status]?.contains(next) ?? false;

  Order moveTo(OrderStatus next) {
    if (!canMoveTo(next)) {
      throw StateError('Order $id: ${status.name} -> ${next.name} is not allowed');
    }
    return Order(id, next);
  }
}

void main() {
  var order = const Order(1001, OrderStatus.placed);
  order = order.moveTo(OrderStatus.paid).moveTo(OrderStatus.accepted);
  print(order.status.name); // accepted
  print(order.canMoveTo(OrderStatus.delivered)); // false: must be picked up first
}

