import 'package:flutter_test/flutter_test.dart';
class Slot {
  final DateTime start;
  final Duration length;
  const Slot(this.start, this.length);
  DateTime get end => start.add(length);
  bool overlaps(Slot o) => start.isBefore(o.end) && o.start.isBefore(end);
}

void main() {
  final a = Slot(DateTime(2026, 10, 3, 10), const Duration(minutes: 20));
  test('back-to-back slots do not overlap', () {
    expect(a.overlaps(Slot(DateTime(2026, 10, 3, 10, 20), a.length)), isFalse);
  });
  test('slots that share time overlap', () {
    expect(a.overlaps(Slot(DateTime(2026, 10, 3, 10, 10), a.length)), isTrue);
  });
}

