import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
class BookButton extends StatefulWidget {
  const BookButton({super.key, required this.onBook});
  final Future<void> Function() onBook;
  @override
  State<BookButton> createState() => _BookButtonState();
}
class _BookButtonState extends State<BookButton> {
  bool _busy = false;
  Future<void> _book() async {
    setState(() => _busy = true);
    await widget.onBook();
    if (mounted) setState(() => _busy = false);
  }
  @override
  Widget build(BuildContext context) => FilledButton(
      onPressed: _busy ? null : _book, child: Text(_busy ? 'در حال ثبت…' : 'رزرو نوبت'));
}
void main() {
  testWidgets('a double tap books only once', (tester) async {
    final done = Completer<void>();
    var calls = 0;
    await tester.pumpWidget(MaterialApp(home: BookButton(onBook: () { calls++; return done.future; })));
    await tester.tap(find.text('رزرو نوبت'));
    await tester.pump();
    await tester.tap(find.byType(FilledButton), warnIfMissed: false);
    expect(calls, 1);
    done.complete();
  });
}

